body::after {
    content: "";
    position: fixed;
    bottom: 0;
    left: 0;
    width: 280px;
    height: 380px;
    background-image: url("https://i.postimg.cc/HLKgmkXD/pinguu.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: bottom left;
    opacity: 0.85;
    pointer-events: none;
    z-index: 999999;
}

body {
    background-color: #1C1D42;
}
